<script lang="ts">import type { Booking } from '$lib/api/types'; import Button from './ui/Button.svelte'; let { bookings, admin = false, onCancel, onStatus }: { bookings: Booking[]; admin?: boolean; onCancel?: (id: number) => void; onStatus?: (id: number, status: 'CONFIRMED' | 'CANCELLED' | 'COMPLETED') => void } = $props(); const date = (value: string) => new Date(value).toLocaleString();</script>
<div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b text-slate-500"><tr><th class="p-2">When</th>{#if admin}<th class="p-2">Customer</th>{/if}<th class="p-2">Employee</th><th class="p-2">Service</th><th class="p-2">Status</th><th class="p-2"></th></tr></thead><tbody>{#each bookings as booking}<tr class="border-b"><td class="p-2 whitespace-nowrap">{date(booking.startTime)}</td>{#if admin}<td class="p-2">{booking.user.name}<br /><span class="text-xs text-slate-500">{booking.user.email}</span></td>{/if}<td class="p-2">{booking.employee.name}</td><td class="p-2">{booking.service.name}</td><td class="p-2"><span class="rounded bg-slate-100 px-2 py-1 text-xs">{booking.status}</span></td><td class="p-2 text-right">{#if admin && onStatus}<select aria-label="Change booking status" class="mr-2 rounded border p-1 text-xs" value={booking.status} onchange={(event) => onStatus(booking.id, event.currentTarget.value as 'CONFIRMED' | 'CANCELLED' | 'COMPLETED')}><option>CONFIRMED</option><option>CANCELLED</option><option>COMPLETED</option></select>{/if}{#if !admin && booking.status === 'CONFIRMED' && onCancel}<Button variant="outline" onclick={() => onCancel(booking.id)}>Cancel</Button>{/if}</td></tr>{/each}</tbody></table></div>
